const rows = $input.first().json;
const doc = Array.isArray(rows) ? rows[0]?.data : rows?.data;
if (!doc) return [];
const balance = b => (b.status === 'cancelled' || b.paymentStatus === 'paid') ? 0 : (b.amount - b.deposit);
const abiertas = (doc.bookings ?? [])
  .filter(b => (b.status === 'confirmed' || b.status === 'completed') && balance(b) > 0)
  .sort((a, b) => Number(b.paymentStatus === 'overdue') - Number(a.paymentStatus === 'overdue'));
if (abiertas.length === 0) return [];
const fmt = n => new Intl.NumberFormat('es-MX').format(n);
const total = abiertas.reduce((acc, b) => acc + balance(b), 0);
const lineas = abiertas.slice(0, 8).map(b => `· ${b.clientName}: $${fmt(balance(b))}${b.paymentStatus === 'overdue' ? ' ⚠ VENCIDO' : ''} (${b.serviceName})`);
const mensaje = [`💰 Cobranza Malonic — $${fmt(total)} MXN abiertos:`, ...lineas, abiertas.length > 8 ? `…y ${abiertas.length - 8} más` : null].filter(Boolean).join('\n');
return [{ json: { mensaje } }];
